const api={PROTOCOL,validTelemetry,controlState,BldcClient,BldcArrows};if(typeof module!=='undefined')module.exports=api;
if(!root.document)return;
const $=id=>document.getElementById(id);let busy=false,connecting=false,pdDirty=false,points=[];
const message=text=>{$('message').textContent=text;};
const client=new BldcClient({onTelemetry:render,onError:async e=>{arrows.reset('USB disconnected.');message(e.message);await client.close();update();}});
const arrows=new BldcArrows({client,canRun:()=>client.fresh()&&client.last?.power_ready&&client.last?.direction_supported===true&&!client.last?.motor_enabled&&!busy,settings:()=>({percent:Number($('speed').value),duration_ms:Number($('duration').value)}),onHint:t=>{$('arrowHint').textContent=t;},onChange:()=>{document.querySelectorAll('[data-arrow]').forEach(b=>b.classList.toggle('engaged',arrows.held.has(b.dataset.arrow)&&!!arrows.direction));}});
function update(){const d=client.last,c=controlState(d,client.fresh(),busy);$('connect').disabled=connecting;$('connect').textContent=client.port?'Disconnect':'Connect motor';$('arm').disabled=!c.arm;$('start').disabled=!(c.arm||c.start);$('request9').disabled=$('pdVoltage').disabled=!c.power||!d?.pd_voltages?.length;$('request9').title=c.power?'Changing voltage stops the motor':'Connect current firmware to change voltage';$('stop').disabled=!client.port;$('speed').disabled=!c.settings;$('duration').disabled=!c.settings||!!d?.motor_enabled;document.querySelectorAll('[data-arrow]').forEach(b=>b.disabled=!client.fresh()||!d?.power_ready||d?.direction_supported!==true||busy);$('speed').max=c.speedMax;if(!client.port){$('state').textContent='Disconnected';$('runStatus').textContent='Connect to begin.';}else if(!client.fresh()){$('state').textContent='Waiting for BLDC telemetry';$('runStatus').textContent='No fresh compatible telemetry; motor controls disabled.';}}
function render(d){arrows.receive(d);if(!pdDirty&&Number.isFinite(d.pd_voltage_requested))$('pdVoltage').value=String(d.pd_voltage_requested);$('state').textContent=d.state.replaceAll('_',' ');$('identity').textContent=`${d.board} · ${d.device_id}`;$('voltage').textContent=d.vmotor_v.toFixed(2);$('current').textContent=d.feed_current_a.toFixed(3);$('frequency').textContent=d.electrical_hz.toFixed(1);$('powerHint').textContent=`PD input ${d.vbus_v.toFixed(2)} V · ${d.power_ready?'motor supply ready':'motor supply not ready'}`;$('motionHint').textContent=`${d.fg_edges} FG edges · ${d.motor_enabled?'drive enabled':'drive disabled'}`;$('runStatus').textContent=!d.motor_enabled&&!d.armed&&d.last_stop_reason&&d.last_stop_reason!=='None'?d.last_stop_reason:d.reason;$('runProgress').hidden=!Number($('duration').value);$('runProgress').value=d.remaining_ms;$('runProgress').max=Number($('duration').value);$('firmwareStatus').textContent=`${d.firmware_version} · ${d.firmware_build}`;$('powerStatus').textContent=d.power_ready?`${d.pd_voltage_requested||9} V ready`:d.vmotor_v<1?'Motor power off':'Waiting for selected voltage';const colors={RUNNING:'#75efd0',STARTING:'#64e0ee',WAITING_FOR_ARM:'#f5bf63',POWER_ON_DISARMED:'#f5bf63',FAULT:'#ff6c78',POWER_NOT_READY:'#ff6c78',LOGIC_ON_MOTOR_POWER_OFF:'#6d9bff',BOOT:'#6d9bff',NEGOTIATING:'#6d9bff'};$('ledDot').style.background=colors[d.led]||'#536173';$('led').textContent='LED '+d.led.toLowerCase().replaceAll('_',' ');points.push({t:Date.now(),v:d.feed_current_a});points=points.filter(p=>p.t>Date.now()-30000).slice(-200);update();draw();}
function draw(){const canvas=$('history'),r=canvas.getBoundingClientRect(),ratio=root.devicePixelRatio||1;canvas.width=Math.max(1,r.width*ratio);canvas.height=Math.max(1,r.height*ratio);const g=canvas.getContext('2d');if(!g)return;g.scale(ratio,ratio);const w=r.width,h=r.height,left=40,bottom=25,top=15,hi=Math.max(.15,...points.map(p=>p.v*1.2)),now=Date.now();g.font='11px system-ui';g.lineWidth=1;for(let i=0;i<=3;i++){let y=top+(h-top-bottom)*i/3;g.strokeStyle='#273445';g.beginPath();g.moveTo(left,y);g.lineTo(w,y);g.stroke();g.fillStyle='#91a3b8';g.fillText((hi*(1-i/3)).toFixed(2),0,y+4);}g.strokeStyle='#75efd0';g.lineWidth=2;g.beginPath();points.forEach((p,i)=>{const x=left+(p.t-(now-30000))/30000*(w-left),y=top+(1-p.v/hi)*(h-top-bottom);i?g.lineTo(x,y):g.moveTo(x,y);});g.stroke();g.fillStyle='#91a3b8';g.fillText('−30 s',left,h-4);g.fillText('now',w-27,h-4);}
